-- NEXORA FORGE ACADEMY INSTALL — PART 19/21
-- Curriculum lessons 289-306 of 324

begin;
insert into public.academy_lessons(id,course_id,title,slug,summary,content_html,starter_code,exercise,status,sort_order,estimated_minutes)
select x.id,c.id,x.title,x.slug,x.summary,x.content_html,x.starter_code,x.exercise,x.status,x.sort_order,x.estimated_minutes
from jsonb_to_recordset($lessons$[{"id":"curriculum-324-javascript-advanced-01","course_id":"javascript-advanced","title":"مدیریت ویژگی‌های شیء با Property Descriptor","slug":"javascript-advanced-01","summary":"Descriptor تعیین می‌کند ویژگی قابل‌نوشتن، حذف و پیمایش باشد یا نه.","content_html":"<h3>هدف درس</h3><p>ویژگی‌های شیء را با descriptor کنترل کن.</p><h3>نمونه و بررسی</h3><p>برای بررسی دقیق از Object.getOwnPropertyDescriptor استفاده کن.</p><pre><code>const item={}; Object.defineProperty(item,\"id\",{value:7,writable:false,enumerable:true}); console.log(Object.getOwnPropertyDescriptor(item,\"id\"));</code></pre><h3>تمرین عملی</h3><p>شیئی بساز که شناسه آن ثابت و عنوانش قابل تغییر باشد.</p><h3>نکته فنی</h3><p>writable و configurable دو کنترل مستقل‌اند.</p><h3>معیار موفقیت</h3><p>شناسه تغییرناپذیر بماند و عنوان قابل تغییر باشد.</p>","starter_code":"const item={}; Object.defineProperty(item,\"id\",{value:7,writable:false,enumerable:true}); console.log(Object.getOwnPropertyDescriptor(item,\"id\"));","exercise":"شیئی بساز که شناسه آن ثابت و عنوانش قابل تغییر باشد.","status":"published","sort_order":1,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-02","course_id":"javascript-advanced","title":"Getter و Setter برای اعتبارسنجی","slug":"javascript-advanced-02","summary":"Accessorها خواندن و نوشتن ویژگی را به منطق کنترل‌شده متصل می‌کنند.","content_html":"<h3>هدف درس</h3><p>اعتبارسنجی را در setter انجام بده.</p><h3>نمونه و بررسی</h3><p>Getter بهتر است بدون اثر جانبی باشد.</p><pre><code>const user = {\n  _score: 0,\n  get score() {\n    return this._score;\n  },\n  set score(value) {\n    if (!Number.isFinite(value) || value &lt; 0 || value &gt; 100) {\n      throw new RangeError(\"نمره باید عددی بین صفر تا صد باشد\");\n    }\n    this._score = value;\n  }\n};\nuser.score = 90;\nconsole.log(user.score);</code></pre><h3>تمرین عملی</h3><p>ویژگی progress بساز که فقط عدد بین صفر تا صد بپذیرد.</p><h3>نکته فنی</h3><p>در setter فقط مقایسه بازه کافی نیست؛ NaN با مقایسه‌های معمولی از شرط عبور می‌کند، بنابراین Number.isFinite نیز لازم است.</p><h3>معیار موفقیت</h3><p>مقدار معتبر خوانده شود و مقدار خارج از بازه خطا بدهد.</p>","starter_code":"const user = {\n  _score: 0,\n  get score() {\n    return this._score;\n  },\n  set score(value) {\n    if (!Number.isFinite(value) || value < 0 || value > 100) {\n      throw new RangeError(\"نمره باید عددی بین صفر تا صد باشد\");\n    }\n    this._score = value;\n  }\n};\nuser.score = 90;\nconsole.log(user.score);","exercise":"ویژگی progress بساز که فقط عدد بین صفر تا صد بپذیرد.","status":"published","sort_order":2,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-03","course_id":"javascript-advanced","title":"Proxy برای رهگیری دسترسی","slug":"javascript-advanced-03","summary":"Proxy عملیات روی شیء را با trapهایی مانند get و set رهگیری می‌کند.","content_html":"<h3>هدف درس</h3><p>عملیات شیء را با handler کنترل کن.</p><h3>نمونه و بررسی</h3><p>رفتار عادی را با Reflect حفظ کن.</p><pre><code>const state=new Proxy({theme:\"dark\"},{set(t,k,v){if(k===\"theme\"&amp;&amp;!['dark','light'].includes(v))return false; return Reflect.set(t,k,v)}}); state.theme=\"light\";</code></pre><h3>تمرین عملی</h3><p>تغییر تم را محدود و دسترسی به ویژگی‌ها را ثبت کن.</p><h3>نکته فنی</h3><p>Proxy مرز امنیتی سمت سرور نیست.</p><h3>معیار موفقیت</h3><p>مقدار نامعتبر وارد state نشود.</p>","starter_code":"const state=new Proxy({theme:\"dark\"},{set(t,k,v){if(k===\"theme\"&&!['dark','light'].includes(v))return false; return Reflect.set(t,k,v)}}); state.theme=\"light\";","exercise":"تغییر تم را محدود و دسترسی به ویژگی‌ها را ثبت کن.","status":"published","sort_order":3,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-04","course_id":"javascript-advanced","title":"Reflect و عملیات بازتابی","slug":"javascript-advanced-04","summary":"Reflect API عملیات عمومی شیء را با خروجی قابل پیش‌بینی فراهم می‌کند.","content_html":"<h3>هدف درس</h3><p>عملیات شیء را از طریق Reflect اجرا کن.</p><h3>نمونه و بررسی</h3><p>نتیجه Boolean عملیات را بررسی کن.</p><pre><code>const x={name:\"Ava\"}; Reflect.set(x,\"level\",2); console.log(Reflect.has(x,\"name\"),Reflect.ownKeys(x));</code></pre><h3>تمرین عملی</h3><p>تابعی برای set، has و فهرست کلیدها با Reflect بساز.</p><h3>نکته فنی</h3><p>شکست بعضی عملیات false برمی‌گرداند.</p><h3>معیار موفقیت</h3><p>حالت موفق و ناموفق گزارش شود.</p>","starter_code":"const x={name:\"Ava\"}; Reflect.set(x,\"level\",2); console.log(Reflect.has(x,\"name\"),Reflect.ownKeys(x));","exercise":"تابعی برای set، has و فهرست کلیدها با Reflect بساز.","status":"published","sort_order":4,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-05","course_id":"javascript-advanced","title":"WeakRef و ارجاع ضعیف","slug":"javascript-advanced-05","summary":"WeakRef ارجاعی می‌سازد که به‌تنهایی مانع garbage collection نمی‌شود.","content_html":"<h3>هدف درس</h3><p>ارجاع قوی و ضعیف را مقایسه کن.</p><h3>نمونه و بررسی</h3><p>deref ممکن است undefined بدهد.</p><pre><code>let data={label:\"cache\"}; const ref=new WeakRef(data); console.log(ref.deref()?.label); data=null;</code></pre><h3>تمرین عملی</h3><p>نمونه‌ای بساز که نبود شیء پس از deref را مدیریت کند.</p><h3>نکته فنی</h3><p>زمان GC قابل پیش‌بینی نیست.</p><h3>معیار موفقیت</h3><p>کد در هر دو حالت بدون خطا باشد.</p>","starter_code":"let data={label:\"cache\"}; const ref=new WeakRef(data); console.log(ref.deref()?.label); data=null;","exercise":"نمونه‌ای بساز که نبود شیء پس از deref را مدیریت کند.","status":"published","sort_order":5,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-06","course_id":"javascript-advanced","title":"BigInt برای اعداد صحیح بزرگ","slug":"javascript-advanced-06","summary":"BigInt اعداد صحیح فراتر از محدوده امن Number را دقیق نگه می‌دارد.","content_html":"<h3>هدف درس</h3><p>از پسوند n برای عدد صحیح بزرگ استفاده کن.</p><h3>نمونه و بررسی</h3><p>BigInt و Number را مستقیم در عملیات مخلوط نکن.</p><pre><code>const count=9007199254740993n; console.log(count+7n);</code></pre><h3>تمرین عملی</h3><p>شمارنده بسیار بزرگ را بدون افت دقت افزایش بده.</p><h3>نکته فنی</h3><p>JSON به‌طور پیش‌فرض BigInt را serialize نمی‌کند.</p><h3>معیار موفقیت</h3><p>نتیجه دقیق و تبدیل انتقالی آگاهانه باشد.</p>","starter_code":"const count=9007199254740993n; console.log(count+7n);","exercise":"شمارنده بسیار بزرگ را بدون افت دقت افزایش بده.","status":"published","sort_order":6,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-07","course_id":"javascript-advanced","title":"دقت اعشاری در محاسبات مالی","slug":"javascript-advanced-07","summary":"Number ممیز شناور دودویی است؛ مبلغ را در واحد صحیح کوچک‌تر نگه دار.","content_html":"<h3>هدف درس</h3><p>گرد کردن را تا لایه نمایش به تعویق بینداز.</p><h3>نمونه و بررسی</h3><p>واحد پول را در نام متغیر مشخص کن.</p><pre><code>const pricePul=1250*100; const totalPul=pricePul+2750; console.log(totalPul/100);</code></pre><h3>تمرین عملی</h3><p>سبد خرید را با واحد صحیح پول محاسبه کن.</p><h3>نکته فنی</h3><p>خطای ممیز شناور می‌تواند جمع مالی را مخدوش کند.</p><h3>معیار موفقیت</h3><p>جمع دقیق و سیاست گردکردن مستند باشد.</p>","starter_code":"const pricePul=1250*100; const totalPul=pricePul+2750; console.log(totalPul/100);","exercise":"سبد خرید را با واحد صحیح پول محاسبه کن.","status":"published","sort_order":7,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-08","course_id":"javascript-advanced","title":"TypedArray برای داده عددی","slug":"javascript-advanced-08","summary":"TypedArray داده را با نوع عددی و حافظه فشرده نگه می‌دارد.","content_html":"<h3>هدف درس</h3><p>نوع آرایه را بر اساس دامنه داده انتخاب کن.</p><h3>نمونه و بررسی</h3><p>تبدیل خارج از دامنه را بررسی کن.</p><pre><code>const values=new Int16Array([120,-30,450]); values[1]=25; console.log(values,values.BYTES_PER_ELEMENT);</code></pre><h3>تمرین عملی</h3><p>داده حسگر را در Int16Array ذخیره و مقادیر مرزی را آزمایش کن.</p><h3>نکته فنی</h3><p>مقدار خارج از محدوده ممکن است wrap شود.</p><h3>معیار موفقیت</h3><p>نوع و مقدارهای مرزی درست مدیریت شوند.</p>","starter_code":"const values=new Int16Array([120,-30,450]); values[1]=25; console.log(values,values.BYTES_PER_ELEMENT);","exercise":"داده حسگر را در Int16Array ذخیره و مقادیر مرزی را آزمایش کن.","status":"published","sort_order":8,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-09","course_id":"javascript-advanced","title":"ArrayBuffer و DataView","slug":"javascript-advanced-09","summary":"ArrayBuffer حافظه خام و DataView ابزار خواندن انواع مختلف با کنترل endianness است.","content_html":"<h3>هدف درس</h3><p>offset و نوع داده را دقیق تعیین کن.</p><h3>نمونه و بررسی</h3><p>endianness را در هر دو سمت یکسان بگیر.</p><pre><code>const b=new ArrayBuffer(8),v=new DataView(b); v.setUint32(0,2026,false); v.setFloat32(4,3.5,false); console.log(v.getUint32(0,false),v.getFloat32(4,false));</code></pre><h3>تمرین عملی</h3><p>رکورد باینری با عدد صحیح و اعشاری بساز و بخوان.</p><h3>نکته فنی</h3><p>دسترسی خارج از محدوده RangeError می‌دهد.</p><h3>معیار موفقیت</h3><p>مقادیر خوانده‌شده با مقادیر نوشته‌شده برابر باشند.</p>","starter_code":"const b=new ArrayBuffer(8),v=new DataView(b); v.setUint32(0,2026,false); v.setFloat32(4,3.5,false); console.log(v.getUint32(0,false),v.getFloat32(4,false));","exercise":"رکورد باینری با عدد صحیح و اعشاری بساز و بخوان.","status":"published","sort_order":9,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-10","course_id":"javascript-advanced","title":"structuredClone و کپی عمیق","slug":"javascript-advanced-10","summary":"structuredClone بسیاری از ساختارهای داده را به‌صورت عمیق کپی می‌کند.","content_html":"<h3>هدف درس</h3><p>از کپی عمیق برای snapshot داده استفاده کن.</p><h3>نمونه و بررسی</h3><p>بررسی کن داده قابل clone باشد.</p><pre><code>const a={profile:{name:\"Nima\"}}; const b=structuredClone(a); b.profile.name=\"Ava\"; console.log(a.profile.name,b.profile.name);</code></pre><h3>تمرین عملی</h3><p>شیء تو در تو را مستقل کپی و تغییر بده.</p><h3>نکته فنی</h3><p>تابع و DOM Node قابل clone نیستند.</p><h3>معیار موفقیت</h3><p>تغییر کپی روی اصل اثر نگذارد.</p>","starter_code":"const a={profile:{name:\"Nima\"}}; const b=structuredClone(a); b.profile.name=\"Ava\"; console.log(a.profile.name,b.profile.name);","exercise":"شیء تو در تو را مستقل کپی و تغییر بده.","status":"published","sort_order":10,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-11","course_id":"javascript-advanced","title":"Iterator سفارشی","slug":"javascript-advanced-11","summary":"Iterator قرارداد next با value و done را پیاده می‌کند.","content_html":"<h3>هدف درس</h3><p>قرارداد iterator را اجرا کن.</p><h3>نمونه و بررسی</h3><p>وضعیت پیمایش را داخل iterator نگه دار.</p><pre><code>const range={from:1,to:3,[Symbol.iterator](){let n=this.from;const end=this.to;return{next(){return n&lt;=end?{value:n++,done:false}:{done:true}}}}}; console.log([...range]);</code></pre><h3>تمرین عملی</h3><p>شیء بازه صفحات را برای for...of قابل پیمایش کن.</p><h3>نکته فنی</h3><p>پس از پایان done باید true باشد.</p><h3>معیار موفقیت</h3><p>هر مقدار دقیقاً یک بار و به ترتیب برگردد.</p>","starter_code":"const range={from:1,to:3,[Symbol.iterator](){let n=this.from;const end=this.to;return{next(){return n<=end?{value:n++,done:false}:{done:true}}}}}; console.log([...range]);","exercise":"شیء بازه صفحات را برای for...of قابل پیمایش کن.","status":"published","sort_order":11,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-12","course_id":"javascript-advanced","title":"Generator و تولید تنبل","slug":"javascript-advanced-12","summary":"Generator با yield مقدار را تدریجی تولید و وضعیت اجرا را حفظ می‌کند.","content_html":"<h3>هدف درس</h3><p>از function* و yield استفاده کن.</p><h3>نمونه و بررسی</h3><p>Generator مصرف‌شده از ابتدا restart نمی‌شود.</p><pre><code>function* ids(n){for(let i=1;i&lt;=n;i++)yield `lesson-${i}`} console.log([...ids(3)]);</code></pre><h3>تمرین عملی</h3><p>مولد صفحه‌ها بساز که مقدار بعدی را هنگام درخواست تولید کند.</p><h3>نکته فنی</h3><p>تولید تنبل از ساخت آرایه کامل جلوگیری می‌کند.</p><h3>معیار موفقیت</h3><p>مقدارها به‌ترتیب و تدریجی تولید شوند.</p>","starter_code":"function* ids(n){for(let i=1;i<=n;i++)yield `lesson-${i}`} console.log([...ids(3)]);","exercise":"مولد صفحه‌ها بساز که مقدار بعدی را هنگام درخواست تولید کند.","status":"published","sort_order":12,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-13","course_id":"javascript-advanced","title":"Async Iterator و for await","slug":"javascript-advanced-13","summary":"Async Iterator نتیجه next را به‌صورت Promise می‌دهد و for await آن را پیمایش می‌کند.","content_html":"<h3>هدف درس</h3><p>داده ناهمگام را تدریجی پیمایش کن.</p><h3>نمونه و بررسی</h3><p>ترتیب دریافت را حفظ کن.</p><pre><code>async function* pages() {\n  yield 1;\n  await new Promise(resolve =&gt; setTimeout(resolve, 50));\n  yield 2;\n}\nasync function readPages() {\n  for await (const page of pages()) {\n    console.log(page);\n  }\n}\nreadPages();</code></pre><h3>تمرین عملی</h3><p>جریان صفحه‌های نتایج را با مکث ناهمگام تولید کن.</p><h3>نکته فنی</h3><p>این نمونه در یک فایل معمولی نیز اجرا می‌شود، چون حلقه for await داخل تابع async قرار گرفته است.</p><h3>معیار موفقیت</h3><p>هر صفحه پس از آماده شدن پردازش شود.</p>","starter_code":"async function* pages() {\n  yield 1;\n  await new Promise(resolve => setTimeout(resolve, 50));\n  yield 2;\n}\nasync function readPages() {\n  for await (const page of pages()) {\n    console.log(page);\n  }\n}\nreadPages();","exercise":"جریان صفحه‌های نتایج را با مکث ناهمگام تولید کن.","status":"published","sort_order":13,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-14","course_id":"javascript-advanced","title":"Promise.all برای عملیات مستقل","slug":"javascript-advanced-14","summary":"Promise.all همه نتایج را به ترتیب ورودی برمی‌گرداند و با رد شدن یکی، کل Promise رد می‌شود.","content_html":"<h3>هدف درس</h3><p>عملیات مستقل را موازی اجرا کن.</p><h3>نمونه و بررسی</h3><p>پاسخ HTTP ناموفق را خودت reject کن.</p><pre><code>async function loadDashboard() {\n  const [profile, courses] = await Promise.all([\n    fetch(\"/api/profile\").then(response =&gt; {\n      if (!response.ok) throw new Error(`HTTP ${response.status}`);\n      return response.json();\n    }),\n    fetch(\"/api/courses\").then(response =&gt; {\n      if (!response.ok) throw new Error(`HTTP ${response.status}`);\n      return response.json();\n    })\n  ]);\n  console.log(profile, courses);\n}\nloadDashboard().catch(console.error);</code></pre><h3>تمرین عملی</h3><p>دو منبع مستقل داشبورد را هم‌زمان دریافت کن.</p><h3>نکته فنی</h3><p>نمونه داخل تابع async قرار دارد؛ برای هر پاسخ HTTP نیز response.ok بررسی شده تا خطای 404 به‌اشتباه موفقیت تلقی نشود.</p><h3>معیار موفقیت</h3><p>هر دو نتیجه پس از موفقیت در دسترس باشند.</p>","starter_code":"async function loadDashboard() {\n  const [profile, courses] = await Promise.all([\n    fetch(\"/api/profile\").then(response => {\n      if (!response.ok) throw new Error(`HTTP ${response.status}`);\n      return response.json();\n    }),\n    fetch(\"/api/courses\").then(response => {\n      if (!response.ok) throw new Error(`HTTP ${response.status}`);\n      return response.json();\n    })\n  ]);\n  console.log(profile, courses);\n}\nloadDashboard().catch(console.error);","exercise":"دو منبع مستقل داشبورد را هم‌زمان دریافت کن.","status":"published","sort_order":14,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-15","course_id":"javascript-advanced","title":"Promise.allSettled برای تاب‌آوری","slug":"javascript-advanced-15","summary":"allSettled وضعیت همه Promiseها را حتی در صورت شکست بعضی از آن‌ها جمع‌آوری می‌کند.","content_html":"<h3>هدف درس</h3><p>وضعیت هر عملیات را جداگانه پردازش کن.</p><h3>نمونه و بررسی</h3><p>پیش از خواندن value یا reason، status را بررسی کن.</p><pre><code>async function inspectPanels() {\n  const results = await Promise.allSettled([\n    Promise.resolve(\"profile\"),\n    Promise.reject(new Error(\"offline\"))\n  ]);\n  for (const result of results) {\n    if (result.status === \"fulfilled\") console.log(\"ready:\", result.value);\n    else console.error(\"failed:\", result.reason);\n  }\n}\ninspectPanels();</code></pre><h3>تمرین عملی</h3><p>سه پنل مستقل را بارگذاری کن و موفق‌ها را حتی با شکست یکی نمایش بده.</p><h3>نکته فنی</h3><p>برای هر نتیجه ابتدا status بررسی می‌شود؛ فقط نتیجه fulfilled دارای value و نتیجه rejected دارای reason است.</p><h3>معیار موفقیت</h3><p>موفقیت و شکست هر بخش جدا نمایش داده شود.</p>","starter_code":"async function inspectPanels() {\n  const results = await Promise.allSettled([\n    Promise.resolve(\"profile\"),\n    Promise.reject(new Error(\"offline\"))\n  ]);\n  for (const result of results) {\n    if (result.status === \"fulfilled\") console.log(\"ready:\", result.value);\n    else console.error(\"failed:\", result.reason);\n  }\n}\ninspectPanels();","exercise":"سه پنل مستقل را بارگذاری کن و موفق‌ها را حتی با شکست یکی نمایش بده.","status":"published","sort_order":15,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-16","course_id":"javascript-advanced","title":"Promise.race و timeout","slug":"javascript-advanced-16","summary":"race با نخستین Promise تعیین‌تکلیف‌شده نتیجه می‌دهد اما عملیات بازنده را متوقف نمی‌کند.","content_html":"<h3>هدف درس</h3><p>حد انتظار را مستقل از درخواست تعریف کن.</p><h3>نمونه و بررسی</h3><p>برای توقف واقعی fetch از signal استفاده کن.</p><pre><code>const timeout=new Promise((_,reject)=&gt;setTimeout(()=&gt;reject(Error(\"timeout\")),2000)); Promise.race([fetch('/api/status'),timeout]).catch(console.error);</code></pre><h3>تمرین عملی</h3><p>timeout بساز و نسخه دارای AbortController را برای لغو واقعی اضافه کن.</p><h3>نکته فنی</h3><p>race به‌تنهایی منابع عملیات بازنده را آزاد نمی‌کند.</p><h3>معیار موفقیت</h3><p>timeout گزارش و درخواست در نسخه نهایی لغو شود.</p>","starter_code":"const timeout=new Promise((_,reject)=>setTimeout(()=>reject(Error(\"timeout\")),2000)); Promise.race([fetch('/api/status'),timeout]).catch(console.error);","exercise":"timeout بساز و نسخه دارای AbortController را برای لغو واقعی اضافه کن.","status":"published","sort_order":16,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-17","course_id":"javascript-advanced","title":"Promise.any و نخستین موفقیت","slug":"javascript-advanced-17","summary":"Promise.any نخستین fulfilled را می‌دهد و اگر همه رد شوند AggregateError می‌دهد.","content_html":"<h3>هدف درس</h3><p>از چند منبع نخستین موفقیت را بگیر.</p><h3>نمونه و بررسی</h3><p>پاسخ HTTP ناموفق را به rejection تبدیل کن.</p><pre><code>Promise.any([Promise.reject(\"A\"),Promise.resolve(\"mirror B\")]).then(console.log).catch(e=&gt;console.log(e.errors));</code></pre><h3>تمرین عملی</h3><p>دو منبع جایگزین را بررسی و نخستین پاسخ معتبر را انتخاب کن.</p><h3>نکته فنی</h3><p>همه شکست‌ها در AggregateError قرار می‌گیرند.</p><h3>معیار موفقیت</h3><p>یک موفقیت کافی باشد و شکست همگانی گزارش شود.</p>","starter_code":"Promise.any([Promise.reject(\"A\"),Promise.resolve(\"mirror B\")]).then(console.log).catch(e=>console.log(e.errors));","exercise":"دو منبع جایگزین را بررسی و نخستین پاسخ معتبر را انتخاب کن.","status":"published","sort_order":17,"estimated_minutes":40},{"id":"curriculum-324-javascript-advanced-18","course_id":"javascript-advanced","title":"Top-level await در ES Module","slug":"javascript-advanced-18","summary":"ماژول می‌تواند پیش از export، داده ناهمگام را در سطح بالا دریافت کند.","content_html":"<h3>هدف درس</h3><p>آماده‌سازی async در سطح ماژول انجام بده.</p><h3>نمونه و بررسی</h3><p>فایل باید با type=module بارگذاری شود.</p><pre><code>const response=await fetch('/config.json'); if(!response.ok) throw Error('config'); export const config=await response.json();</code></pre><h3>تمرین عملی</h3><p>ماژول پیکربندی بساز که قبل از export تنظیمات را آماده کند.</p><h3>نکته فنی</h3><p>وابستگی‌های واردکننده ممکن است منتظر بمانند.</p><h3>معیار موفقیت</h3><p>مصرف‌کننده فقط پیکربندی آماده دریافت کند.</p>","starter_code":"const response=await fetch('/config.json'); if(!response.ok) throw Error('config'); export const config=await response.json();","exercise":"ماژول پیکربندی بساز که قبل از export تنظیمات را آماده کند.","status":"published","sort_order":18,"estimated_minutes":40}]$lessons$::jsonb) as x(id text,course_id text,title text,slug text,summary text,content_html text,starter_code text,exercise text,status text,sort_order integer,estimated_minutes integer)
join (values
('html','html','beginner'),('html-intermediate','html','intermediate'),('html-advanced','html','advanced'),
('css','css','beginner'),('css-intermediate','css','intermediate'),('css-advanced','css','advanced'),
('javascript','javascript','beginner'),('javascript-intermediate','javascript','intermediate'),('javascript-advanced','javascript','advanced')
) as cp(course_id,language_id,level_id) on cp.course_id=x.course_id
join public.academy_courses c on c.language_id=cp.language_id and c.level_id=cp.level_id
on conflict(id) do update set title=excluded.title,slug=excluded.slug,summary=excluded.summary,content_html=excluded.content_html,starter_code=excluded.starter_code,exercise=excluded.exercise,status='published',sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,archived_at=null,updated_at=now();
commit;
